const collect = (n, depth = 0) => {
  const item = {
    id: n.id,
    name: n.name,
    type: n.type,
    description: 'description' in n ? n.description : undefined,
    annotations: 'annotations' in n ? n.annotations : undefined,
  };
  const children = [];
  if ('children' in n && depth < 4) {
    for (const c of n.children) {
      children.push(collect(c, depth + 1));
    }
  }
  return { ...item, children };
};
