  const text = root.innerText;
  const numbered = Array.from(root.querySelectorAll('ol, ul, li, [data-offset-key]')).map(el => ({
    tag: el.tagName,
    text: (el.innerText || '').slice(0, 300)
  })).slice(0, 20);
