const labels = [];
for (const id of ['251:7378','251:7384','251:7385','251:7386']) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) {
    labels.push({ id, missing: true });
    continue;
  }
  let text = '';
  if (n.type === 'TEXT') text = n.characters;
  if ('findAllWithCriteria' in n) {
    const texts = n.findAllWithCriteria({ types: ['TEXT'] }).map(t => t.characters);
    text = texts.join(' | ');
  }
  labels.push({ id, name: n.name, type: n.type, text });
}
return labels;
